<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>LeLiLu - Testimoni</title>
  <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap" rel="stylesheet"/>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --yellow: #F5C518;
      --dark: #111;
      --gray: #888;
      --light-gray: #f5f5f5;
      --border: #e5e5e5;
      --white: #fff;
      --blue-badge: #4A6CF7;
    }

    body {
      font-family: 'Poppins', sans-serif;
      background: var(--white);
      color: var(--dark);
    }

    /* ===== NAVBAR ===== */
    nav {
      display: flex;
      align-items: center;
      gap: 0;
      border-bottom: 1px solid var(--border);
      padding: 0;
    }

    .nav-logo {
      font-weight: 800;
      font-size: 1.15rem;
      padding: 18px 28px;
      border-right: 1px solid var(--border);
      letter-spacing: -0.5px;
    }

    .nav-links {
      display: flex;
      list-style: none;
    }

    .nav-links li a {
      display: block;
      padding: 18px 28px;
      text-decoration: none;
      color: var(--dark);
      font-size: 0.9rem;
      font-weight: 500;
      border-right: 1px solid var(--border);
      transition: color 0.2s;
    }

    .nav-links li a:hover,
    .nav-links li a.active {
      color: var(--yellow);
    }

    /* ===== BREADCRUMB ===== */
    .breadcrumb {
      padding: 10px 28px;
      background: var(--light-gray);
      font-size: 0.82rem;
      color: var(--gray);
      border-bottom: 1px solid var(--border);
    }

    .breadcrumb a {
      color: var(--gray);
      text-decoration: none;
    }

    .breadcrumb span {
      color: var(--yellow);
      font-weight: 600;
    }

    /* ===== MAIN ===== */
    main {
      padding: 36px 28px 60px;
      max-width: 1100px;
    }

    /* ===== PAGE TITLE ===== */
    .page-title-wrap {
      display: flex;
      align-items: center;
      gap: 18px;
      margin-bottom: 32px;
    }

    .page-title {
      font-size: 2.2rem;
      font-weight: 800;
      letter-spacing: -1px;
    }

    .title-line {
      flex: 1;
      max-width: 200px;
      height: 5px;
      background: var(--yellow);
      border-radius: 3px;
    }

    /* ===== GRID ===== */
    .testimonial-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    /* ===== CARD ===== */
    .card {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 22px 20px 18px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      min-height: 160px;
      box-shadow: 0 1px 4px rgba(0,0,0,0.04);
      transition: box-shadow 0.2s, transform 0.2s;
    }

    .card:hover {
      box-shadow: 0 6px 24px rgba(0,0,0,0.09);
      transform: translateY(-2px);
    }

    .card-text {
      font-size: 0.84rem;
      line-height: 1.65;
      color: #333;
      margin-bottom: 20px;
      flex: 1;
    }

    .card-author {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .avatar-wrap {
      position: relative;
      width: 38px;
      height: 38px;
      flex-shrink: 0;
    }

    .avatar {
      width: 38px;
      height: 38px;
      border-radius: 50%;
      object-fit: cover;
      display: block;
    }

    /* Colored avatar placeholder */
    .avatar-placeholder {
      width: 38px;
      height: 38px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 0.9rem;
      color: #fff;
    }

    .badge {
      position: absolute;
      bottom: 0;
      right: -2px;
      background: var(--blue-badge);
      border-radius: 50%;
      width: 14px;
      height: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      border: 2px solid var(--white);
    }

    .badge svg {
      width: 7px;
      height: 7px;
      fill: white;
    }

    .author-info {
      display: flex;
      flex-direction: column;
    }

    .author-name {
      font-size: 0.82rem;
      font-weight: 700;
      color: var(--dark);
    }

    .author-handle {
      font-size: 0.75rem;
      color: var(--gray);
    }

    /* ===== FOOTER IMAGE AREA ===== */
    .footer-art {
      width: 100%;
      height: 220px;
      margin-top: 40px;
      overflow: hidden;
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 800px) {
      .testimonial-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 520px) {
      .testimonial-grid { grid-template-columns: 1fr; }
      .page-title { font-size: 1.6rem; }
    }
  </style>
</head>
<body>

<!-- NAVBAR -->
<nav>
